from lib import build
R=[]
R.append((7891662,
("Murgh salun (curry de pollo)","Sirva este platillo con arroz o pan naan para mojar los deliciosos jugos, y con un acompañamiento de verduras al vapor.","6","311 g",
 ["1 cucharada de aceite de oliva","2 cebollas grandes, picadas","4 dientes de ajo, picados","1 cucharada de jengibre fresco, picado","8 tomates, picados","3 chiles verdes, finamente picados","1.5 cucharaditas de chile en polvo","12 muslos de pollo pequeños (75 g cada uno)","1.5 cucharaditas de garam masala","4 cucharadas de yogur natural bajo en grasa"],
 ["Caliente el aceite en una olla, agregue la cebolla, el ajo y el jengibre y fría hasta que estén ligeramente dorados.","Agregue los tomates, los chiles verdes y el chile en polvo, mezcle bien y siga cocinando hasta que la cebolla se ablande. Agregue 2 cucharadas de agua y revuelva.","Agregue los trozos de pollo a la olla junto con el garam masala, el yogur y 200 ml de agua, tape y cocine a fuego lento de 8 a 10 minutos, hasta que el pollo esté cocido."],
 ["Podría usar filete de pavo o pechuga de pollo en lugar de muslos.","Para una versión vegetariana, agregue 2 latas de 400 g de garbanzos y 250 g de champiñones enteros en lugar del pollo.","Instrucciones para congelar: Se puede congelar una vez cocinado. Descongele en el refrigerador o en el microondas y recaliente hasta que esté bien caliente por completo.","@FV"],[]),
("مرغ سالون (كاري الدجاج)","قدّم هذا الطبق مع الأرز أو خبز النان لتغمس به العصارة اللذيذة، ومع طبق جانبي من الخضار المطهوة على البخار.","6","311 جم",
 ["1 ملعقة كبيرة من زيت الزيتون","2 حبة بصل كبيرة، مفرومة","4 فصوص ثوم، مفرومة","1 ملعقة كبيرة من الزنجبيل الطازج، مفروم","8 حبات طماطم، مقطعة","3 حبات فلفل حار أخضر، مفرومة ناعمًا","1.5 ملعقة صغيرة من مسحوق الفلفل الحار","12 فخذ دجاج صغيرة (75 جم لكل فخذ)","1.5 ملعقة صغيرة من الجرام ماسالا","4 ملاعق كبيرة من الزبادي الطبيعي قليل الدسم"],
 ["سخّن الزيت في قدر، وأضف البصل والثوم والزنجبيل وقلّبها حتى تصبح بنية فاتحة.","أضف الطماطم والفلفل الحار الأخضر ومسحوق الفلفل الحار، واخلط جيدًا وواصل الطهي حتى يذبل البصل. أضف 2 ملعقة كبيرة من الماء وقلّب.","أضف قطع الدجاج إلى القدر مع الجرام ماسالا والزبادي و200 مل من الماء، وغطِّه واتركه على نار هادئة لمدة 8-10 دقائق حتى ينضج الدجاج."],
 ["يمكنك استخدام شرائح الديك الرومي أو صدر الدجاج بدلًا من الأفخاذ.","للحصول على نسخة نباتية، أضف 2 علبة (400 جم لكل علبة) من الحمص و250 جم من الفطر الكامل بدلًا من الدجاج.","تعليمات التجميد: يمكن تجميده بعد الطهي. اتركه ليذوب في الثلاجة أو الميكروويف وأعد تسخينه حتى يصبح ساخنًا تمامًا.","@FV"],[])))
R.append((7892992,
("Bocaditos de polenta con manzana y especias","Estos bocaditos de polenta son un dulce ideal para buffets y para picar en fiestas.","25","31 g",
 ["300 ml de agua hirviendo","20 g de azúcar","8 tabletas de stevia","1 cucharadita colmada de jengibre molido","1 cucharadita colmada de canela molida","½ cucharadita rasa de clavos de olor molidos","40 g de pasas","15 g de cáscara de cítricos confitada","100 g de polenta instantánea","1 manzana sin pelar, sin corazón y rallada","1 huevo, batido","50 ml de aceite de canola","½ cucharadita de polvo para hornear","moldecitos de papel/aluminio para hornear","3 cerezas confitadas, 6 almendras blanqueadas y 1 cucharadita de piñones, para decorar"],
 ["Precaliente el horno a 180 °C (marca de gas 4).","Ponga el agua en una olla junto con el azúcar, la stevia, el jengibre, la canela, los clavos, las pasas y la cáscara confitada. Revuelva y lleve al punto de ebullición, revolviendo hasta que el azúcar se disuelva.","Incorpore poco a poco la polenta y siga revolviendo de 4 a 5 minutos hasta que espese; luego retire del fuego.","En un tazón, mezcle la manzana, el huevo, el aceite y el polvo para hornear, y luego incorpore enérgicamente a la polenta.","Distribuya con una cuchara en 25 moldecitos y colóquelos en una bandeja para hornear. Cubra cada uno con media cereza confitada, una almendra o unos cuantos piñones.","Meta al horno y hornee de 16 a 20 minutos, hasta que la parte superior esté ligeramente dorada."],
 [],[]),
("لقيمات البولينتا بالتفاح والتوابل","لقيمات البولينتا هذه حلوى مثالية للبوفيهات ولتناولها كوجبة خفيفة في الحفلات.","25","31 جم",
 ["300 مل من الماء المغلي","20 جم من السكر","8 أقراص ستيفيا","1 ملعقة صغيرة مكتنزة من الزنجبيل المطحون","1 ملعقة صغيرة مكتنزة من القرفة المطحونة","½ ملعقة صغيرة مستوية من القرنفل المطحون","40 جم من الزبيب","15 جم من قشور الحمضيات المسكّرة","100 جم من البولينتا سريعة التحضير","1 حبة تفاح غير مقشّرة، منزوعة القلب ومبشورة","1 بيضة، مخفوقة","50 مل من زيت الكانولا","½ ملعقة صغيرة من البيكنج باودر","قوالب خبز ورقية/ألمنيوم صغيرة","3 حبات كرز مسكّر، و6 حبات لوز مقشّر، و1 ملعقة صغيرة من الصنوبر، للتزيين"],
 ["سخّن الفرن مسبقًا إلى 180° مئوية (درجة الغاز 4).","ضع الماء في قدر مع السكر والستيفيا والزنجبيل والقرفة والقرنفل والزبيب والقشور المسكّرة. قلّب واتركه حتى يصل إلى درجة الغليان مع التحريك حتى يذوب السكر.","أضف البولينتا تدريجيًا مع التحريك المستمر لمدة 4-5 دقائق حتى تتكاثف، ثم ارفعها عن النار.","في وعاء، اخلط التفاح والبيض والزيت والبيكنج باودر، ثم قلّبه بقوة مع البولينتا.","وزّع الخليط بالملعقة في 25 قالبًا وضعها على صينية خبز. زيّن كل واحدة بنصف حبة كرز مسكّر أو حبة لوز أو بضع حبات صنوبر.","ضعها في الفرن واخبزها لمدة 16-20 دقيقة حتى يحمر وجهها قليلًا."],
 [],[])))
R.append((7895649,
("Galletas de Halloween","Una versión baja en azúcar de la galleta de jengibre y avena del norte de Inglaterra. Se sirven tradicionalmente en la noche de las hogueras y son ideales para Halloween.","24","22 g",
 ["50 ml de aceite de canola","10 g de melaza negra (blackstrap)","100 ml de leche descremada","100 g de harina integral","100 g de avena molida (oatmeal)","1 cucharadita rasa de polvo para hornear","3 cucharaditas de jengibre en polvo","1 cucharadita de mezcla de especias dulces","12 cucharaditas de endulzante","1 huevo, batido","1 plátano maduro, bien triturado (unos 100 g)"],
 ["Precaliente el horno a 150 °C (marca de gas 2). Ponga el aceite, la melaza y la leche en una olla y caliente suavemente durante 2 minutos.","En un tazón, mezcle la harina, la avena, el polvo para hornear, el jengibre, las especias dulces y el endulzante. Incorpore batiendo el huevo y el plátano triturado.","Forre con papel pergamino una bandeja para hornear de 30 cm x 20 cm. Incorpore suavemente la mezcla de aceite al tazón y vierta en el molde forrado hasta alcanzar un grosor de aproximadamente 1 cm. Hornee en el centro del horno durante una hora, o hasta que el centro del bizcocho esté apenas firme al tacto.","Retire del horno y deje enfriar en el molde de 15 a 20 minutos. Pase a una tabla de cortar y corte en formas o cuadrados."],
 ["Usamos formas de Halloween para la fotografía, pero también puede cortarlas en los cuadrados más tradicionales. O puede preparar el bizcocho en una bandeja más honda y cortarlo en cubitos más pequeños.","La melaza negra es alta en azúcar pero tiene un sabor intenso, así que solo necesita un poco para darle mucho sabor a su receta.","@FV"],[]),
("بسكويت الهالوين","نسخة قليلة السكر من بسكويت الزنجبيل والشوفان الشمالي. يُقدَّم تقليديًا في ليلة الأضواء (Bonfire Night) وهو مثالي للهالوين.","24","22 جم",
 ["50 مل من زيت الكانولا","10 جم من دبس السكر الأسود (بلاك ستراب)","100 مل من الحليب منزوع الدسم","100 جم من دقيق القمح الكامل","100 جم من دقيق الشوفان","1 ملعقة صغيرة مستوية من البيكنج باودر","3 ملاعق صغيرة من الزنجبيل المطحون","1 ملعقة صغيرة من خليط التوابل الحلوة","12 ملعقة صغيرة من المُحلّي","1 بيضة، مخفوقة","1 حبة موز ناضجة، مهروسة جيدًا (نحو 100 جم)"],
 ["سخّن الفرن مسبقًا إلى 150° مئوية (درجة الغاز 2). ضع الزيت والدبس والحليب في قدر وسخّنها بهدوء لمدة 2 دقيقة.","في وعاء، اخلط الدقيق ودقيق الشوفان والبيكنج باودر والزنجبيل والتوابل الحلوة والمُحلّي. أضف البيض والموز المهروس واخفقهما.","بطّن صينية خبز قياس 30 سم × 20 سم بورق الزبدة. أضف خليط الزيت إلى الوعاء بلطف مع التقليب، ثم اسكبه في الصينية المبطنة حتى يصل سمكه إلى 1 سم تقريبًا. اخبزه في وسط الفرن لمدة 1 ساعة أو حتى يصبح وسط الكعكة متماسكًا قليلًا عند لمسه.","أخرجه من الفرن واتركه يبرد في الصينية لمدة 15-20 دقيقة. انقله إلى لوح تقطيع وقطّعه إلى أشكال أو مربعات."],
 ["استخدمنا أشكال الهالوين في الصورة، ولكن يمكنك تقطيعه إلى مربعات تقليدية أكثر. أو يمكنك تحضير الكعكة في صينية أعمق وتقطيعها إلى مكعبات أصغر.","دبس السكر الأسود غني بالسكر ولكن طعمه قوي، لذا تحتاج إلى القليل منه فقط لإضفاء نكهة كبيرة على وصفتك.","@FV"],[])))
R.append((7897038,
("Buñuelos de calabacín con salsa","Acompañados de una salsa cítrica, estos buñuelos son una guarnición o acompañamiento perfecto.","4","191 g",
 ["1 huevo, batido","una pizca de pimienta negra","15 g de queso parmesano, rallado muy fino","50 g de harina integral","½ cucharadita de polvo para hornear","2 calabacines, rallados","4 cebollines, en rodajas finas (reservando 1 cucharada para servir)","2 cucharaditas de aceite de canola","10 hojas de menta fresca, finamente picadas","3 tomates, picados","½ cebolla morada, finamente picada","½ cucharadita de semillas de comino","una buena pizca de pimienta negra","Jugo de 1 limón verde fresco"],
 ["Ponga el huevo batido, la pimienta, el queso parmesano, la harina y el polvo para hornear en un tazón y mezcle bien.","Incorpore el calabacín y el cebollín (reservando 1 cucharada para servir).","Ponga el aceite en una sartén grande antiadherente, coloque 1 cucharada de la mezcla en la sartén y aplánela ligeramente para formar un buñuelo de unos ¾ a 1 cm de grosor, y repita por tandas hasta terminar la mezcla. (Dependiendo del tamaño de su sartén, podrá cocinar de 3 a 4 buñuelos a la vez.) A medida que los buñuelos estén listos, colóquelos en un plato y resérvelos.","Cocine los buñuelos de 2 a 3 minutos, hasta que estén ligeramente dorados, luego voltéelos y cocine el otro lado (nuevamente de 2 a 3 minutos).","Mientras tanto, ponga todos los ingredientes de la salsa en un tazón. Mezcle bien y reserve.","Cuando todos los buñuelos estén listos, espolvoree con el cebollín restante y sirva con la salsa. (Puede servir los buñuelos tibios o fríos.)"],
 ["Para una alternativa vegetariana al parmesano, cámbielo por un queso duro de tipo vegetariano.","@FV"],[]),
("فطائر الكوسا مع الصلصة","مع صلصة منعشة بنكهة الحمضيات، تُعدّ هذه الفطائر طبقًا جانبيًا أو مرافقًا مثاليًا.","4","191 جم",
 ["1 بيضة، مخفوقة","رشة من الفلفل الأسود","15 جم من جبن البارميزان، مبشور ناعمًا جدًا","50 جم من دقيق القمح الكامل","½ ملعقة صغيرة من البيكنج باودر","2 حبة كوسا، مبشورة","4 حبات بصل أخضر، مقطعة إلى شرائح رفيعة (مع الاحتفاظ بـ 1 ملعقة كبيرة للتقديم)","2 ملعقة صغيرة من زيت الكانولا","10 أوراق نعناع طازجة، مفرومة ناعمًا","3 حبات طماطم، مقطعة","½ حبة بصل أحمر، مفرومة ناعمًا","½ ملعقة صغيرة من بذور الكمون","رشة وافرة من الفلفل الأسود","عصير 1 ليمونة خضراء طازجة"],
 ["ضع البيض المخفوق والفلفل وجبن البارميزان والدقيق والبيكنج باودر في وعاء واخلطها جيدًا.","أضف الكوسا والبصل الأخضر (مع الاحتفاظ بـ 1 ملعقة كبيرة للتقديم) واخلطها.","ضع الزيت في مقلاة كبيرة غير لاصقة، وضع فيها 1 ملعقة كبيرة من الخليط وسوِّها قليلًا لتكوين فطيرة بسمك ¾-1 سم تقريبًا، وكرر ذلك على دفعات حتى ينتهي الخليط. (بحسب حجم مقلاتك، يمكنك طهي 3-4 فطائر في المرة الواحدة.) وعندما تنضج الفطائر، ضعها في طبق وضعه جانبًا.","اطهِ الفطائر لمدة 2-3 دقائق حتى تحمر قليلًا، ثم اقلبها واطهِ الجانب الآخر (لمدة 2-3 دقائق أيضًا).","في هذه الأثناء، ضع جميع مكونات الصلصة في وعاء. اخلطها جيدًا وضعها جانبًا.","عندما تنضج جميع الفطائر، انثر عليها البصل الأخضر المتبقي وقدّمها مع الصلصة. (يمكنك تقديم الفطائر دافئة أو باردة.)"],
 ["للحصول على بديل نباتي للبارميزان، استبدله بجبن صلب مناسب للنباتيين.","@FV"],[])))
R.append((7897849,
("Pescado con papas fritas y chícharos, ¡fabuloso!","Esta versión es igual de sabrosa y más saludable que la de las tiendas de pescado frito.","2","520 g",
 ["2 papas grandes (400 g), cortadas en papas fritas gruesas y precocidas durante 5 minutos","2 cucharaditas de aceite de canola + 1 cucharadita para el pescado","2 trozos de 200 g de filete de pescado blanco a su elección","2 cucharaditas colmadas de harina común","200 g de chícharos congelados","2 cucharaditas de salsa tártara","2 cucharaditas de yogur bajo en grasa","rodajas de limón y pimienta negra recién molida, para servir"],
 ["Precaliente el horno a 220 ºC (marca de gas 7).","Mezcle las papas precocidas con 2 cucharaditas de aceite y sazone con abundante pimienta negra. Extienda las papas sobre una bandeja para hornear antiadherente y cocine de 25 a 30 minutos, hasta que estén doradas y tiernas.","Mientras tanto, coloque los filetes de pescado en un plato y enharínelos, asegurándose de que queden bien cubiertos.","Caliente una sartén antiadherente a fuego medio y agregue la cucharadita de aceite restante, extendiéndola por la sartén con papel de cocina.","Sacuda el exceso de harina y coloque con cuidado los filetes de pescado en la sartén; cocine de 3 a 4 minutos por cada lado.","Caliente los chícharos en una olla pequeña con agua hirviendo, escúrralos y triture toscamente. Mezcle la salsa tártara con el yogur.","Sirva el pescado, las papas fritas, los chícharos y la salsa tártara con un poco de pimienta negra, una rodaja de limón y una guarnición de ensalada."],
 ["Enharinar el pescado antes de freírlo evita que la superficie del pescado se queme.","Para darle más sabor, puede sazonar la harina: solo con sal y pimienta, o con especias como cinco especias chino o pimentón ahumado.","Use harina fina de garbanzo como alternativa sin gluten.","@FV"],[]),
("سمك وبطاطس مقلية وبازلاء رائعة","هذه النسخة لذيذة بالقدر نفسه وأكثر صحة من نسخة محلات السمك المقلي.","2","520 جم",
 ["2 حبة بطاطس كبيرة (400 جم)، مقطعة إلى أصابع سميكة ومسلوقة جزئيًا لمدة 5 دقائق","2 ملعقة صغيرة من زيت الكانولا + 1 ملعقة صغيرة للسمك","2 قطعة (200 جم لكل قطعة) من فيليه السمك الأبيض من اختيارك","2 ملعقة صغيرة مكتنزة من الدقيق العادي","200 جم من البازلاء المجمّدة","2 ملعقة صغيرة من صلصة التارتار","2 ملعقة صغيرة من الزبادي قليل الدسم","شرائح ليمون وفلفل أسود مطحون طازجًا للتقديم"],
 ["سخّن الفرن مسبقًا إلى 220° مئوية (درجة الغاز 7).","قلّب أصابع البطاطس المسلوقة جزئيًا مع 2 ملعقة صغيرة من الزيت وتبّلها بكمية وافرة من الفلفل الأسود. وزّعها على صينية خبز غير لاصقة واتركها تنضج لمدة 25-30 دقيقة حتى تصبح ذهبية وطرية.","في هذه الأثناء، ضع شرائح السمك على طبق وقلّبها في الدقيق مع التأكد من تغطيتها جيدًا.","سخّن مقلاة غير لاصقة على نار متوسطة وأضف ملعقة الزيت الصغيرة المتبقية، ومرّرها على سطح المقلاة بورق المطبخ.","انفض الدقيق الزائد وضع شرائح السمك في المقلاة بحذر واطهها لمدة 3-4 دقائق على كل جانب.","سخّن البازلاء في قدر صغير من الماء المغلي، ثم صفِّها واهرسها هرسًا خشنًا. اخلط صلصة التارتار مع الزبادي.","قدّم السمك والبطاطس والبازلاء وصلصة التارتار مع رشة من الفلفل الأسود وشريحة ليمون وقليل من السلطة للتزيين."],
 ["تقليب السمك في الدقيق قبل القلي يمنع احتراق سطح السمك.","للحصول على نكهة أكثر، يمكنك إضافة التتبيلة إلى الدقيق – ملح وفلفل فقط، أو توابل مثل مسحوق التوابل الخمسة الصيني أو البابريكا المدخّنة.","استخدم دقيق الحمص الناعم كبديل خالٍ من الغلوتين.","@FV"],[])))
R.append((7900276,
("Sopa de res y cebada","Esto no es solo una sopa: es una comida sustanciosa ideal para los días de invierno, cocinada toda en una sola olla.","4","441 g",
 ["1 cucharadita de aceite de canola","2 cebollas grandes, finamente picadas","250 g de carne molida de res magra (5 % de grasa)","2 dientes de ajo, machacados","2 zanahorias, picadas","1 colinabo pequeño, finamente picado","1 puerro mediano, finamente picado","2 tallos de apio, picados","20 g de harina común","1 cubo de caldo de res bajo en sal, disuelto en 1.5 L de agua","50 g de cebada perlada","½ cucharadita de tomillo seco","una pizca de pimienta","2 cucharaditas de cebollín picado, para decorar"],
 ["Caliente el aceite de canola en una olla, agregue las cebollas y cocine suavemente durante 5 minutos, revolviendo con regularidad.","Agregue la carne molida y revuelva durante 5 minutos hasta que empiece a dorarse, deshaciendo los grumos con una cuchara de madera.","Agregue el ajo, las zanahorias, el colinabo, el puerro y el apio y cocine durante 5 minutos, revolviendo con regularidad.","Espolvoree la harina sobre la carne molida y las verduras, mezclando bien. Incorpore el caldo de res.","Mezcle de nuevo, agregue la cebada perlada, el tomillo y la pimienta, lleve a ebullición, baje el fuego, tape y cocine a fuego lento durante 30 minutos. Sirva con un poco de cebollín espolvoreado."],
 ["Puede prepararla con carne molida de cordero, o usar carne molida de pavo para un platillo más bajo en grasa.","Para una versión vegana, reemplace la carne de res con una lata de lentejas verdes y un cubo de caldo de verduras bajo en sal.","Para concentrar aún más los sabores, puede cocinar sin tapa para reducir la cantidad de líquido.","Instrucciones para congelar: Se puede congelar una vez cocinada. Puede congelarse en recipientes pequeños para porciones individuales. Descongele en el microondas o en la estufa, a fuego muy bajo, hasta que esté bien caliente.","@FV"],[]),
("شوربة اللحم البقري والشعير","هذه ليست مجرد شوربة، بل وجبة مشبعة مثالية لأيام الشتاء، تُطهى كلها في قدر واحد.","4","441 جم",
 ["1 ملعقة صغيرة من زيت الكانولا","2 حبة بصل كبيرة، مفرومة ناعمًا","250 جم من لحم البقر المفروم الخالي من الدهن (5% دهون)","2 فص ثوم، مهروس","2 حبة جزر، مقطعة","1 حبة لفت سويدي صغيرة، مفرومة ناعمًا","1 حبة كراث متوسطة، مفرومة ناعمًا","2 ساق كرفس، مقطعة","20 جم من الدقيق العادي","1 مكعب مرق لحم بقري قليل الملح، مذاب في 1.5 لتر من الماء","50 جم من الشعير المقشور (اللؤلؤي)","½ ملعقة صغيرة من الزعتر المجفف","رشة من الفلفل","2 ملعقة صغيرة من الثوم المعمر المفروم للتزيين"],
 ["سخّن زيت الكانولا في قدر، وأضف البصل ثم اطهه بهدوء لمدة 5 دقائق مع التحريك بانتظام.","أضف اللحم البقري المفروم وقلّبه لمدة 5 دقائق حتى يبدأ بالاحمرار، مع تفتيت أي كتل بملعقة خشبية.","أضف الثوم والجزر واللفت السويدي والكراث والكرفس واطهها لمدة 5 دقائق مع التحريك بانتظام.","انثر الدقيق فوق اللحم المفروم والخضار مع الخلط جيدًا. أضف مرق اللحم البقري وقلّب.","اخلط مرة أخرى، وأضف الشعير اللؤلؤي والزعتر والفلفل، واتركها حتى تغلي، ثم خفّف الحرارة وغطِّها واتركها على نار هادئة لمدة 30 دقيقة. قدّمها مع رشة من الثوم المعمر."],
 ["يمكنك تحضيرها باستخدام لحم الضأن المفروم، أو استخدام لحم الديك الرومي المفروم للحصول على طبق أقل دسمًا.","للحصول على نسخة نباتية صرفة، استبدل اللحم البقري بعلبة من العدس الأخضر ومكعب مرق خضار قليل الملح.","لتركيز النكهات أكثر، يمكنك الطهي دون غطاء لتقليل كمية السائل.","تعليمات التجميد: يمكن تجميدها بعد الطهي. يمكن تجميدها في أوعية صغيرة للحصص الفردية. اتركها لتذوب في الميكروويف أو على الموقد، على نار هادئة جدًا حتى تصبح ساخنة تمامًا.","@FV"],[])))
R.append((7900398,
("Quesadillas de frijoles picantes","Frijoles y verduras picantes en crujientes sándwiches de tortilla integral.","2","304 g",
 ["2 tortillas integrales","1 cucharada de mantequilla de almendra","½ lata de frijoles pintos, triturados toscamente","1 cucharada de puré de tomate","80 g de chícharos congelados, descongelados y triturados toscamente","½ cucharadita de comino molido","½ cucharadita de orégano","½ cucharadita de chile en polvo suave","2 cebollines, finamente picados","1 tomate, finamente picado","½ pimiento verde, finamente picado","1 cucharada de cilantro fresco, picado toscamente, más un poco para servir","1 cucharada de cebolla morada finamente picada, para servir"],
 ["Unte ligeramente las tortillas con la mantequilla de frutos secos.","Mezcle todo lo demás, excepto la cebolla morada, y extienda sobre una tortilla; coloque la otra tortilla encima.","Cocine en una sartén antiadherente a fuego bajo (sin necesidad de aceite) hasta que la tortilla se dore y quede crujiente.","Voltee la tortilla y cocine el otro lado (de 3 a 5 minutos por cada lado).","Colóquela sobre una tabla y corte en rebanadas; luego esparza la cebolla morada y el cilantro. Sirva con ensalada."],
 ["Puede preparar las tortillas con anticipación y freírlas cuando esté listo para comer.","@FV"],[]),
("كيساديا الفاصولياء الحارة","فاصولياء وخضار حارة داخل شطائر تورتيلا القمح الكامل المقرمشة.","2","304 جم",
 ["2 رغيف تورتيلا قمح كامل","1 ملعقة كبيرة من زبدة اللوز","½ علبة من فاصولياء البينتو، مهروسة هرسًا خشنًا","1 ملعقة كبيرة من معجون الطماطم","80 جم من البازلاء المجمّدة، مذابة ومهروسة هرسًا خشنًا","½ ملعقة صغيرة من الكمون المطحون","½ ملعقة صغيرة من الأوريجانو","½ ملعقة صغيرة من مسحوق الفلفل الحار الخفيف","2 حبة بصل أخضر، مفرومة ناعمًا","1 حبة طماطم، مفرومة ناعمًا","½ حبة فلفل رومي أخضر، مفرومة ناعمًا","1 ملعقة كبيرة من الكزبرة الخضراء الطازجة، مفرومة فرمًا خشنًا، مع قليل منها للتقديم","1 ملعقة كبيرة من البصل الأحمر المفروم ناعمًا للتقديم"],
 ["ادهن أرغفة التورتيلا برفق بزبدة المكسرات.","اخلط جميع المكونات الأخرى ما عدا البصل الأحمر، وافردها على رغيف واحد من التورتيلا، ثم ضع الرغيف الآخر فوقها.","اطهها في مقلاة غير لاصقة على نار هادئة (دون الحاجة إلى زيت) حتى تبدأ التورتيلا بالاحمرار وتصبح مقرمشة.","اقلب التورتيلا واطهِ الجانب الآخر (لمدة 3-5 دقائق على كل جانب).","ضعها على لوح وقطّعها إلى شرائح، ثم انثر عليها البصل الأحمر والكزبرة الخضراء. قدّمها مع السلطة."],
 ["يمكنك تحضير التورتيلا مسبقًا وقليها عندما تكون جاهزًا للأكل.","@FV"],[])))
R.append((7902347,
("Tajín marroquí de calabaza y berenjena","Una versión vegetariana del clásico del norte de África, llena de sustanciosas verduras de raíz.","4","496 g",
 ["2 cucharaditas de aceite de canola","2 cebollas moradas, picadas","2 berenjenas, picadas en trozos grandes","1 calabaza butternut mediana, pelada, sin semillas y en cubos (750 g)","6 dientes de ajo, machacados","1 trozo de jengibre de 5 cm","1 a 2 chiles (al gusto, picantes o suaves), finamente picados","200 ml de agua","1 lata de 400 g de tomates picados","2 cucharaditas de canela","1 cucharadita de cúrcuma","2 cucharaditas de comino","rodaja de limón verde, para servir"],
 ["Ponga el aceite en una olla, seguido de la cebolla, y revuelva de 3 a 4 minutos hasta que apenas empiece a dorarse.","A continuación, agregue la berenjena y la calabaza butternut. Caliente de 3 a 4 minutos, revolviendo con regularidad.","Agregue el ajo, el jengibre y el chile y cocine de 1 a 2 minutos, revolviendo con regularidad.","Agregue la canela, la cúrcuma y el comino. Mezcle bien, vierta el agua, revuelva y luego agregue los tomates.","Mezcle bien y lleve a un hervor suave. Baje el fuego, tape y cocine a fuego lento durante 15 minutos, hasta que la calabaza esté blanda.","Mezcle y sirva con cilantro fresco, además de unas rodajas de limón."],
 ["Si no tiene calabaza butternut, pruebe con camotes o con una mezcla de otras verduras de raíz, como zanahoria, chirivía y colinabo.","@FV"],[]),
("طاجين القرع والباذنجان المغربي","نسخة نباتية من الطبق الكلاسيكي الشمال أفريقي – مليئة بالخضار الجذرية المشبعة.","4","496 جم",
 ["2 ملعقة صغيرة من زيت الكانولا","2 حبة بصل أحمر، مقطعة","2 حبة باذنجان، مقطعة قطعًا كبيرة","1 حبة قرع باترنت متوسطة، مقشّرة ومنزوعة البذور ومقطعة مكعبات (750 جم)","6 فصوص ثوم، مهروسة","1 قطعة زنجبيل بطول 5 سم","1-2 حبة فلفل حار (حسب الرغبة، حار أو خفيف)، مفرومة ناعمًا","200 مل من الماء","1 علبة (400 جم) من الطماطم المقطعة","2 ملعقة صغيرة من القرفة","1 ملعقة صغيرة من الكركم","2 ملعقة صغيرة من الكمون","شريحة ليمون أخضر للتقديم"],
 ["ضع الزيت في قدر، ثم أضف البصل وقلّبه لمدة 3-4 دقائق حتى يبدأ بالاحمرار.","بعد ذلك، أضف الباذنجان وقرع الباترنت. سخّنها لمدة 3-4 دقائق مع التحريك بانتظام.","أضف الثوم والزنجبيل والفلفل الحار واطهها لمدة 1-2 دقيقة مع التحريك بانتظام أيضًا.","أضف القرفة والكركم والكمون. اخلط جيدًا، واسكب الماء وقلّب، ثم أضف الطماطم.","اخلط جيدًا واتركها حتى تغلي غليًا هادئًا. خفّف الحرارة وغطِّها واتركها على نار هادئة لمدة 15 دقيقة حتى يلين القرع.","قلّب وقدّم مع الكزبرة الخضراء الطازجة، بالإضافة إلى بعض شرائح الليمون."],
 ["إذا لم يتوفر لديك قرع الباترنت، فجرّب البطاطا الحلوة أو مزيجًا من الخضار الجذرية الأخرى، مثل الجزر والجزر الأبيض واللفت السويدي.","@FV"],[])))
R.append((7903857,
("Huevos al horno","Puerros cremosos y champiñones horneados con huevos: un desayuno sabroso, sencillo pero diferente.","4","136 g",
 ["1 cucharadita de aceite de canola","1 puerro (160 g), en rodajas finas","160 g de champiñones, en rebanadas","2 cucharadas de yogur estilo griego 0 % grasa","una buena pizca de pimienta blanca","4 huevos"],
 ["Precaliente el horno a 180 °C (marca de gas 4).","Ponga el aceite en una olla, luego agregue los puerros y los champiñones y cocine de 4 a 5 minutos, revolviendo con regularidad.","Incorpore el yogur y la pimienta, luego divida la mezcla entre 4 recipientes aptos para horno.","Haga un pequeño hueco en el centro de cada recipiente y rompa un huevo en cada uno. Hornee de 12 a 15 minutos, o más, según cómo le gusten los huevos."],
 ["Pruebe a agregar un pimiento rojo finamente picado junto con los puerros y los champiñones.","Agregue un poco de cebollín picado o albahaca fresca para darle más sabor.","Los grupos «en riesgo», como los bebés, los niños, las mujeres embarazadas, los ancianos y las personas enfermas, deben evitar los huevos crudos o poco cocidos, a menos que puedan garantizar que se hayan producido bajo el programa de garantía de calidad del código Lion.","@FV"],[]),
("بيض مخبوز","كراث وفطر كريمي مخبوز مع البيض – فطور لذيذ بسيط لكنه مختلف.","4","136 جم",
 ["1 ملعقة صغيرة من زيت الكانولا","1 حبة كراث (160 جم)، مقطعة إلى شرائح رفيعة","160 جم من الفطر، مقطع إلى شرائح","2 ملعقة كبيرة من الزبادي اليوناني الخالي من الدسم 0%","رشة وافرة من الفلفل الأبيض","4 بيضات"],
 ["سخّن الفرن مسبقًا إلى 180° مئوية (درجة الغاز 4).","ضع الزيت في قدر، ثم أضف الكراث والفطر واطهها لمدة 4-5 دقائق مع التحريك بانتظام.","أضف الزبادي والفلفل وقلّب، ثم وزّع الخليط على 4 أوعية تصلح للفرن.","اصنع تجويفًا صغيرًا في وسط كل وعاء، ثم اكسر بيضة في كل منها. اخبزها لمدة 12-15 دقيقة أو أكثر بحسب الطريقة التي تفضّل بها البيض."],
 ["جرّب إضافة حبة فلفل رومي أحمر مفرومة ناعمًا مع الكراث والفطر.","أضف بعض الثوم المعمر المفروم أو الريحان الطازج للحصول على نكهة أكثر.","ينبغي على الفئات «المعرّضة للخطر» مثل الرضع والأطفال والحوامل وكبار السن والمرضى تجنّب البيض الطري/قليل النضج والنيء، ما لم يكن بإمكانهم التأكد من أنه أُنتج بموجب برنامج ضمان الجودة «Lion code».","@FV"],[])))
R.append((7905259,
("Pasta al horno con frijoles y chile","Un platillo que le dará calor en invierno y que puede preparar con lo que tiene en la despensa.","2","371 g",
 ["1 cebolla pequeña, picada","½ pimiento rojo, picado","1 diente de ajo, machacado","100 g de carne molida de res magra","1 lata de 230 g de tomates picados","2 cucharadas de puré de tomate","½ cucharadita de chile en polvo","una pizca de pimentón","75 g de pasta integral seca en formas, cocida y escurrida","1 lata de 215 g de frijoles rojos, escurridos y enjuagados","1 cucharada de perejil fresco, picado","25 g de pan molido integral","15 g de queso parmesano rallado"],
 ["Ponga la cebolla, el pimiento, el ajo y la carne molida en una sartén antiadherente y fría durante 5 minutos, hasta que la carne se dore y las cebollas empiecen a ablandarse. Agregue a la sartén los tomates, el puré de tomate, el chile en polvo y el pimentón, lleve a ebullición, tape y cocine a fuego lento durante 10 minutos.","Mientras tanto, cocine la pasta según las instrucciones del paquete.","Incorpore los frijoles rojos y el perejil a la pasta y caliente bien. Pase a una fuente para horno. Mezcle el pan molido con el queso parmesano y espolvoree sobre la pasta.","Coloque la fuente bajo un grill precalentado de 1 a 2 minutos, hasta que esté dorada."],
 ["Para darle un sabor tex-mex, agregue 1 cucharadita rasa de comino molido y 1 de orégano seco.","También puede rellenar con esta mezcla de chile pimientos cortados por la mitad, cubrir con queso Cheddar desmenuzado y hornear durante 20 minutos.","@FV"],[]),
("معكرونة بالفاصولياء والفلفل الحار في الفرن","طبق يدفئ أجواء الشتاء ويمكنك تحضيره بسرعة من مخزن طعامك.","2","371 جم",
 ["1 حبة بصل صغيرة، مفرومة","½ حبة فلفل رومي أحمر، مفرومة","1 فص ثوم، مهروس","100 جم من لحم البقر المفروم الخالي من الدهن","1 علبة (230 جم) من الطماطم المقطعة","2 ملعقة كبيرة من معجون الطماطم","½ ملعقة صغيرة من مسحوق الفلفل الحار","رشة من البابريكا","75 جم من المعكرونة الجافة بأشكال مختلفة من القمح الكامل، مطبوخة ومصفّاة","1 علبة (215 جم) من الفاصولياء الحمراء، مصفّاة ومغسولة","1 ملعقة كبيرة من البقدونس الطازج، مفروم","25 جم من فتات خبز القمح الكامل","15 جم من جبن البارميزان المبشور"],
 ["ضع البصل والفلفل الرومي والثوم واللحم المفروم في مقلاة غير لاصقة وقلّبها لمدة 5 دقائق حتى يتحمر اللحم ويبدأ البصل بالذبول. أضف الطماطم ومعجون الطماطم ومسحوق الفلفل الحار والبابريكا إلى المقلاة، واتركها حتى تغلي، ثم غطِّها واتركها على نار هادئة لمدة 10 دقائق.","في هذه الأثناء، اطهِ المعكرونة حسب تعليمات العبوة.","أضف الفاصولياء الحمراء والبقدونس إلى المعكرونة وقلّب حتى تسخن. انقلها إلى وعاء يصلح للفرن. اخلط فتات الخبز مع جبن البارميزان وانثره فوق المعكرونة.","ضع الوعاء تحت شواية مسخّنة مسبقًا لمدة 1-2 دقيقة حتى يصبح ذهبي اللون."],
 ["للحصول على نكهة التكس-ميكس، أضف 1 ملعقة صغيرة مستوية من الكمون المطحون و1 ملعقة صغيرة مستوية من الأوريجانو المجفف.","يمكنك أيضًا حشو حبات فلفل رومي مقطعة إلى نصفين بخليط الفلفل الحار هذا، وتغطيتها بجبن شيدر مفتت وخبزها لمدة 20 دقيقة.","@FV"],[])))
R.append((7905699,
("Estofado etíope de res","Un estofado picante de res, que se sirve tradicionalmente con pan plano injera.","4","477 g",
 ["2 cucharaditas de aceite de girasol","500 g de carne de res para estofar, cortada en cubos","2 cebollas, picadas","3 vainas de cardamomo","1 cucharadita de semillas de cilantro","2 clavos de olor enteros","2 cucharaditas de semillas de comino","2 chiles verdes, picados","4 dientes de ajo, en rodajas","1 cucharadita de canela molida","1 cucharadita de cúrcuma molida","2 pimientos verdes, picados","1 lata de 400 g de tomates picados","2 zanahorias, picadas en trozos grandes","2 papas (200 g cada una), cortadas en trozos","100 g de lentejas rojas","1 litro de agua"],
 ["Caliente el aceite en una olla y agregue la carne de res y las cebollas. Cocine durante 5 minutos, revolviendo con regularidad, hasta que empiecen a dorarse.","Agregue todos los demás ingredientes, revuelva y lleve a ebullición. Baje el fuego, tape la olla y cocine a fuego lento durante 1.5 a 2 horas, revolviendo de vez en cuando. Sirva el estofado con la injera (vea los consejos del chef)."],
 ["4 injeras preparadas con 150 g de harina de teff, una pizca grande de sal y 180 g de agua + 2 cucharaditas de aceite para freír (la receta no está incluida en la información nutricional)","Puede usar cordero o pollo en lugar de res.","Si no tiene lentejas secas, una lata está bien: busque las enlatadas en agua sin sal añadida y agréguelas durante los últimos 30 minutos de cocción. Los frijoles adzuki funcionan bien en lugar de las lentejas.","Instrucciones para congelar: Se puede congelar una vez cocinado. Descongele en el refrigerador o en el microondas y recaliente hasta que esté bien caliente por completo.","@FV"],[]),
("يخنة اللحم البقري الإثيوبية","يخنة لحم بقري حارة، تُقدَّم تقليديًا مع خبز الإنجيرا المسطح.","4","477 جم",
 ["2 ملعقة صغيرة من زيت عباد الشمس","500 جم من لحم البقر المخصص للطهي البطيء، مقطع مكعبات","2 حبة بصل، مفرومة","3 قرون هيل","1 ملعقة صغيرة من بذور الكزبرة","2 مسمار قرنفل كامل","2 ملعقة صغيرة من بذور الكمون","2 حبة فلفل حار أخضر، مفرومة","4 فصوص ثوم، مقطعة إلى شرائح","1 ملعقة صغيرة من القرفة المطحونة","1 ملعقة صغيرة من الكركم المطحون","2 حبة فلفل رومي أخضر، مفرومة","1 علبة (400 جم) من الطماطم المقطعة","2 حبة جزر، مقطعة قطعًا كبيرة","2 حبة بطاطس (200 جم لكل حبة)، مقطعة قطعًا","100 جم من العدس الأحمر","1 لتر من الماء"],
 ["سخّن الزيت في قدر وأضف اللحم البقري والبصل. اطهها لمدة 5 دقائق مع التحريك بانتظام حتى يبدأ التحمير.","أضف جميع المكونات الأخرى، وقلّب واتركها حتى تغلي. خفّف الحرارة وضع غطاء القدر واتركها تنضج على نار هادئة لمدة 1.5-2 ساعة مع التحريك من حين لآخر. قدّم اليخنة مع الإنجيرا (انظر نصائح الطاهي)."],
 ["4 أرغفة إنجيرا مصنوعة من 150 جم من دقيق التيف ورشة كبيرة من الملح و180 جم من الماء + 2 ملعقة صغيرة من الزيت للقلي (الوصفة غير مشمولة في المعلومات الغذائية)","يمكنك استخدام لحم الضأن أو الدجاج بدلًا من لحم البقر.","إذا لم يتوفر لديك عدس جاف، فلا بأس بالعدس المعلب – ابحث عن العدس المعلب في الماء دون ملح مضاف وأضفه في آخر 30 دقيقة من الطهي. يناسب فاصولياء أدوكي أيضًا بدلًا من العدس.","تعليمات التجميد: يمكن تجميدها بعد الطهي. اتركها لتذوب في الثلاجة أو الميكروويف وأعد تسخينها حتى تصبح ساخنة تمامًا.","@FV"],[])))
R.append((7908780,
("Pan de soda de cebolla caramelizada, pimiento rojo y calabacín","Un pan bajo en grasa, rico en verduras. Ideal para partir y compartir.","12","161 g",
 ["4 cucharaditas de aceite de canola","2 cebollas moradas (240 g), en rodajas finas","2 pimientos rojos (260 g), en rodajas finas","1 calabacín (180 g), cortado en cubitos finos","4 dientes de ajo, machacados","15 g de tomate seco, picado en trozos pequeños","25 g de albahaca fresca, picada","1 cucharadita de orégano seco","2 buenas pizcas de pimienta negra","600 g de harina integral","1 cucharadita de polvo para hornear","50 g de queso Cheddar, cortado en cubitos finos","2 cucharadas colmadas de yogur 0 % grasa","500 ml de agua"],
 ["Precaliente el horno a 180 °C (marca de gas 4).","Ponga 2 cucharaditas del aceite en una olla con las cebollas y revuelva de 3 a 4 minutos. Luego, agregue los pimientos y cocine otros 4 a 5 minutos, revolviendo con regularidad.","Agregue el calabacín y cocine otros 3 a 4 minutos, revolviendo con regularidad.","Retire la olla del fuego, deje enfriar un poco y luego agregue los tomates secos, la albahaca, el orégano y la pimienta.","Ponga el aceite restante en un molde metálico para tarta/quiche o en una bandeja para hornear grande.","En un tazón grande, ponga la harina, el polvo para hornear y ¾ del queso.","Agregue el yogur e incorpore poco a poco el agua.","Incorpore las verduras, mezcle con energía y luego vierta la mezcla en el molde. Espolvoree con el queso restante y hornee de 30 a 35 minutos."],
 ["Pruebe con otras verduras, como puerros, o experimente con diferentes quesos, como feta o parmesano.","Instrucciones para congelar: Se puede congelar una vez cocinado. Descongele en el refrigerador o en el microondas y recaliente hasta que esté bien caliente por completo.","@FV"],[]),
("خبز الصودا بالبصل المكرمل والفلفل الأحمر والكوسا","خبز غني بالخضار وقليل الدسم. مثالي للتقطيع باليد والمشاركة.","12","161 جم",
 ["4 ملاعق صغيرة من زيت الكانولا","2 حبة بصل أحمر (240 جم)، مقطعة إلى شرائح رفيعة","2 حبة فلفل رومي أحمر (260 جم)، مقطعة إلى شرائح رفيعة","1 حبة كوسا (180 جم)، مقطعة مكعبات صغيرة","4 فصوص ثوم، مهروسة","15 جم من الطماطم المجففة، مفرومة قطعًا صغيرة","25 جم من الريحان الطازج، مفروم","1 ملعقة صغيرة من الأوريجانو المجفف","2 رشة وافرة من الفلفل الأسود","600 جم من دقيق القمح الكامل","1 ملعقة صغيرة من البيكنج باودر","50 جم من جبن الشيدر، مقطع مكعبات صغيرة","2 ملعقة كبيرة مكتنزة من الزبادي 0% دسم","500 مل من الماء"],
 ["سخّن الفرن مسبقًا إلى 180° مئوية (درجة الغاز 4).","ضع 2 ملعقة صغيرة من الزيت في قدر مع البصل وقلّب لمدة 3-4 دقائق. بعد ذلك، أضف الفلفل الرومي واطهه 4-5 دقائق أخرى مع التحريك بانتظام.","أضف الكوسا واطهها 3-4 دقائق أخرى مع التحريك بانتظام.","ارفع القدر عن النار واتركه يبرد قليلًا، ثم أضف الطماطم المجففة والريحان والأوريجانو والفلفل.","ضع باقي الزيت في قالب فلان/كيش معدني أو على صينية خبز كبيرة.","في وعاء كبير، ضع الدقيق والبيكنج باودر و¾ كمية الجبن.","أضف الزبادي وقلّب الماء تدريجيًا.","أضف الخضار وقلّب بقوة، ثم ضع الخليط في قالب الخبز. انثر الجبن المتبقي فوقه واخبزه لمدة 30-35 دقيقة."],
 ["جرّب خضارًا أخرى، مثل الكراث، أو جرّب أنواعًا مختلفة من الجبن، مثل الفيتا أو البارميزان.","تعليمات التجميد: يمكن تجميده بعد الطهي. اتركه ليذوب في الثلاجة أو الميكروويف وأعد تسخينه حتى يصبح ساخنًا تمامًا.","@FV"],[])))
build(4,R)
